\begin{aligned}
f(y,\theta) &= y - R \theta = 0,\\
\frac{\mathrm{d^2}}{\mathrm{d} t^2} f(y,\theta) &=  \ddot{y} - R \ddot{\theta} =0 \implies \ddot{y} = R \ddot{\theta} .
\end{aligned}

\left\{
